/**
 * Make the camera an OPTIONAL hardware feature, so LiAI is not filtered
 * out of camera-less devices on the Play Store.
 *
 * Declaring `android.permission.CAMERA` implicitly implies
 * `android.hardware.camera` and `android.hardware.camera.autofocus` with an
 * implicit `required="true"`. The permission itself stays (the vision tab
 * still wants it wherever a camera exists) — only the hardware gate relaxes.
 *
 * This is a config plugin rather than a hand edit of
 * `android/app/src/main/AndroidManifest.xml` because `/android/` is
 * gitignored and regenerated by `expo prebuild`: a direct manifest edit
 * silently disappears on the next clean build, which is the worst failure
 * mode for a Play Store reach fix — it looks done until it is undone.
 */

const { withAndroidManifest } = require("@expo/config-plugins");

/** `camera.any` is what modern Android devices actually report. */
const OPTIONAL_CAMERA_FEATURES = [
  "android.hardware.camera",
  "android.hardware.camera.any",
];

module.exports = function withOptionalCameraHardware(config) {
  return withAndroidManifest(config, (config) => {
    const manifest = config.modResults.manifest;
    const features = (manifest["uses-feature"] ??= []);

    for (const name of OPTIONAL_CAMERA_FEATURES) {
      const already = features.some(
        (feature) => feature?.$?.["android:name"] === name,
      );
      // Idempotent. prebuild runs more than once across a normal workflow,
      // and a duplicated uses-feature is a manifest-merge error, not a
      // harmless repeat.
      if (already) continue;
      features.push({ $: { "android:name": name, "android:required": "false" } });
    }

    return config;
  });
};
